import time
from ..errors import ServiceError

class SearchService:
    def __init__(self, embedding, store, vectors, min_score=0.57):
        self.embedding, self.store, self.vectors = embedding, store, vectors
        self.min_score = min_score
        self.entities = {entity for chunk in store.all_chunks() for entity in chunk['entity_names']} if hasattr(store, 'all_chunks') else set()

    def matched_entities(self, question):
        singles = [term for term in self.entities if len(term) == 1 and term in question]
        terms = [term for term in self.entities if len(term) >= 2 and term not in {'京剧', '行当', '角色'} and term in question]
        compound_singles = set(singles) if len(singles) >= 2 else set()
        terms.extend(compound_singles)
        return sorted({term for term in terms if term in compound_singles or not any(term != longer and term in longer for longer in terms)}, key=lambda term: (-len(term), term))

    def search(self, question: str, top_k=5, category=None, mode='vector') -> dict:
        started = time.perf_counter()
        try: vector = self.embedding.encode_query(question)
        except ValueError:
            raise ServiceError('QUESTION_TOKEN_LIMIT', '问题超过Embedding长度限制，请缩短后重试。', 400)
        vector_hits = self.vectors.search(vector, limit=10 if mode == 'hybrid' else min(10, max(top_k, 5)), category=category)
        scores = {h['chunk_id']: h['score'] for h in vector_hits}
        ids = [h['chunk_id'] for h in vector_hits]
        keyword = {}
        entity_coverage = {}
        matched_entities = []
        if mode == 'hybrid':
            matched_entities = self.matched_entities(question)
            lexical = self.store.lexical_search(question, limit=10, entity_terms=matched_entities)
            missing = [hit['chunk_id'] for hit in lexical if hit['chunk_id'] not in scores]
            extra_vectors = self.vectors.search(vector, limit=10, category=category, candidate_ids=missing) if missing else []
            scores.update({hit['chunk_id']: hit['score'] for hit in extra_vectors})
            keyword = {h['chunk_id']: h['keyword_score'] for h in lexical}
            ranking = {cid: 1/(60+i) for i, cid in enumerate(ids, 1)}
            for i, hit in enumerate(lexical, 1):
                ranking[hit['chunk_id']] = ranking.get(hit['chunk_id'], 0) + 1/(60+i)
            # Exact metadata entities distinguish "净" from "正净" and a
            # broad taxonomy mention from sections addressing the named roles.
            # RRF breaks ties; this is an explicit lexical re-ranker, not a
            # reranker model or a new semantic score.
            entity_coverage = {cid: sum(term in self.store.chunk(cid)['entity_names'] for term in matched_entities) for cid in ranking}
            ids = sorted(ranking, key=lambda cid: (entity_coverage[cid], ranking[cid]), reverse=True)
        evidence = []
        for cid in ids:
            # Exact corpus entities provide an explicit lexical route for short
            # summaries. Their actual Qdrant scores are never relabelled as
            # having passed the semantic threshold. The answer layer still
            # checks evidence support of all question premises.
            if cid not in scores or (scores[cid] < self.min_score and cid not in keyword and not entity_coverage.get(cid)): continue
            chunk = self.store.chunk(cid)
            if category and chunk['category'] != category: continue
            source = chunk['source']
            evidence.append({'id': cid, 'chunkId': cid, 'sourceId': chunk['source_id'], 'sectionId': chunk['section_id'], 'title': source['title'], 'locator': chunk['locator'], 'url': source['source_url'], 'excerpt': chunk['content'], 'contentKind': source['content_kind'], 'category': chunk['category'], 'entityNames': chunk['entity_names'], 'vectorScore': scores[cid], 'keywordScore': keyword.get(cid), 'entityMatchCount': entity_coverage.get(cid, 0), 'acceptedBy': 'vector_threshold' if scores[cid] >= self.min_score else ('exact_entity_keyword' if cid in keyword else 'exact_entity_metadata'), 'rank': len(evidence)+1, 'reviewStatus': source['review_status']})
            if len(evidence) >= top_k: break
        return {'question': question, 'evidence': evidence, 'uncertain': not bool(evidence), 'retrievalMode': mode, 'matchedEntities': matched_entities, 'elapsedSeconds': round(time.perf_counter()-started, 4), 'threshold': self.min_score, 'candidateScores': [{'chunkId': h['chunk_id'], 'score': h['score']} for h in vector_hits]}

import json
from pathlib import Path
from pydantic import ValidationError
from ..errors import ServiceError
from ..schemas import GeneratedAnswer

PROMPT = Path(__file__).resolve().parents[2] / 'prompts' / 'rag_answer_v2.txt'

def insufficient(request_id, message='当前京剧知识库没有足够资料支持这个问题，请调整提问方向或补充可信资料。'):
    return {'answer': message, 'citations': [], 'uncertain': True, 'requestId': request_id}

def validated_answer(content: str, evidence: list[dict], request_id: str):
    try:
        data = GeneratedAnswer.model_validate_json(content)
        if not data.answer.strip(): raise ValueError('Empty answer')
        available = {e['id']: e for e in evidence}
        ids = list(dict.fromkeys(data.usedCitationIds))
        if any(cid not in available for cid in ids) or (not data.uncertain and not ids):
            raise ValueError('Unsupported citation')
        citations = [{k: available[cid][k] for k in ('id', 'title', 'sourceId', 'locator', 'url', 'excerpt', 'contentKind')} for cid in ids]
        return {'answer': data.answer, 'citations': citations, 'uncertain': data.uncertain, 'requestId': request_id}
    except (ValueError, ValidationError, TypeError):
        raise ServiceError('ANSWER_EVIDENCE_INVALID', '模型回答未通过引用校验，已停止展示；请调整问题后重试。', 502, True)

async def grounded_answer(question: str, retrieval: dict, provider, request_id: str):
    if retrieval['uncertain']:
        return insufficient(request_id)
    evidence = retrieval['evidence'][:5]
    aliases = {f'E{index}': item['id'] for index, item in enumerate(evidence, 1)}
    model_evidence = [{'id': alias, 'title': item['title'], 'locator': item['locator'], 'excerpt': item['excerpt']} for alias, item in zip(aliases, evidence)]
    messages = [{'role': 'system', 'content': PROMPT.read_text(encoding='utf-8')}, {'role': 'user', 'content': json.dumps({'question': question, 'EVIDENCE': model_evidence}, ensure_ascii=False)}]
    result = await provider.generate(messages, request_id)
    try:
        generated = GeneratedAnswer.model_validate_json(result['content'])
        if any(alias not in aliases for alias in generated.usedCitationIds): raise ValueError('Unknown citation alias')
        generated.usedCitationIds = [aliases[alias] for alias in generated.usedCitationIds]
        canonical_content = generated.model_dump_json()
    except (ValueError, ValidationError, TypeError):
        raise ServiceError('ANSWER_EVIDENCE_INVALID', '模型回答未通过引用校验，已停止展示；请调整问题后重试。', 502, True)
    return validated_answer(canonical_content, evidence, request_id)

"""One official DeepSeek provider. No automatic paid retry or raw error logging."""
import hashlib
import json
import time
from datetime import datetime, timezone
import httpx
from ..errors import ServiceError
from .budget import BudgetLedger

class DeepSeekProvider:
    def __init__(self, settings, transport=None):
        self.settings = settings
        self.transport = transport
        self.ledger = BudgetLedger(settings.rag_data_dir / 'api-budget.sqlite3', settings.rag_test_budget_cny)
        self.probe_path = settings.rag_data_dir / 'provider-readiness.json'

    @property
    def configured(self):
        return bool(self.settings.deepseek_api_key.get_secret_value().strip())

    def fingerprint(self):
        return hashlib.sha256((self.settings.deepseek_model + ':' + self.settings.deepseek_api_key.get_secret_value()).encode()).hexdigest()

    @property
    def verified(self):
        if not self.configured: return False
        try:
            data = json.loads(self.probe_path.read_text(encoding='utf-8'))
            return data.get('success') is True and data.get('configurationFingerprint') == self.fingerprint()
        except (OSError, ValueError): return False

    async def generate(self, messages: list, request_id: str, json_mode=True, max_output=None) -> dict:
        if not self.configured:
            raise ServiceError('LLM_KEY_MISSING', '尚未配置DeepSeek密钥，请在本机私有.env填写后重启后端。')
        limit = self.settings.deepseek_max_output_tokens if max_output is None else max_output
        if not isinstance(limit, int) or isinstance(limit, bool) or not 1 <= limit <= 800:
            raise ServiceError('LLM_OUTPUT_LIMIT', '模型输出长度超过本阶段允许范围。', 400)
        self.ledger.reserve(request_id, messages, limit)
        payload = {'model': self.settings.deepseek_model, 'messages': messages, 'thinking': {'type': 'disabled'}, 'stream': False, 'max_tokens': limit, 'temperature': 0.2}
        if json_mode: payload['response_format'] = {'type': 'json_object'}
        started = time.perf_counter()
        status, usage = 'transport_unknown', None
        try:
            async with httpx.AsyncClient(timeout=self.settings.deepseek_timeout_seconds, transport=self.transport) as client:
                response = await client.post(self.settings.deepseek_base_url + '/chat/completions', headers={'Authorization': 'Bearer ' + self.settings.deepseek_api_key.get_secret_value()}, json=payload)
            status = f'http_{response.status_code}'
            if response.status_code != 200:
                mapping = {400: ('LLM_PARAMETERS', 'DeepSeek参数不兼容，请检查本机模型配置。'), 401: ('LLM_AUTH_FAILED', 'DeepSeek鉴权失败，请在本机检查密钥。'), 402: ('LLM_BALANCE', 'DeepSeek余额不足，请检查账户。'), 404: ('LLM_MODEL', 'DeepSeek模型或接口不可用。'), 429: ('LLM_RATE_LIMIT', 'DeepSeek请求限流，请稍后手动重试。')}
                code, message = mapping.get(response.status_code, ('LLM_UPSTREAM', 'DeepSeek服务暂不可用，请稍后手动重试。'))
                raise ServiceError(code, message, 429 if response.status_code == 429 else 502, response.status_code in (429, 500, 502, 503))
            try:
                body = response.json()
                if not isinstance(body, dict): raise ValueError('invalid body')
                usage = body.get('usage')
                if not isinstance(usage, dict): raise ValueError('invalid usage')
                if any(type(usage.get(key)) is not int or usage[key] < 0 for key in ('prompt_tokens', 'completion_tokens', 'total_tokens')):
                    usage = None
                    raise ValueError('invalid usage values')
                choice = body['choices'][0]
                content = choice['message']['content']
                if not isinstance(content, str) or not content.strip(): raise ValueError('empty')
                if choice.get('finish_reason') == 'length': raise ValueError('truncated')
            except (ValueError, KeyError, IndexError, TypeError):
                raise ServiceError('LLM_INVALID_RESPONSE', '模型返回内容为空或不完整，请缩短问题后手动重试。', 502, True)
            # Do not retain or expose reasoning_content. Only record whether disabled mode was consistent.
            returned_model = body.get('model')
            if not isinstance(returned_model, str) or not (returned_model == 'deepseek-flash' or returned_model.startswith('deepseek-flash-')):
                status = 'invalid_model'
                raise ServiceError('LLM_MODEL_MISMATCH', '返回模型与本阶段批准的模型不一致，已停止展示。', 502)
            reasoning_present = bool(choice['message'].get('reasoning_content'))
            if reasoning_present:
                status = 'invalid_mode'
                raise ServiceError('LLM_MODE_MISMATCH', '模型返回与非思考配置不一致，已停止展示。', 502)
            status = 'success'
            result = {'content': content.strip(), 'model': body.get('model'), 'usage': usage, 'elapsedSeconds': round(time.perf_counter() - started, 4), 'thinkingRequested': 'disabled', 'reasoningContentPresent': False, 'httpStatus': response.status_code}
            self.probe_path.write_text(json.dumps({'success': True, 'configurationFingerprint': self.fingerprint(), 'checkedAt': datetime.now(timezone.utc).isoformat(), 'model': result['model']}, ensure_ascii=False), encoding='utf-8')
            return result
        except httpx.TimeoutException:
            status = 'timeout_unknown'
            raise ServiceError('LLM_TIMEOUT', 'DeepSeek请求超时，未自动重发；请稍后手动重试。', 504, True)
        except httpx.RequestError:
            raise ServiceError('LLM_NETWORK', '无法连接DeepSeek，请检查网络后手动重试。', 503, True)
        finally:
            self.ledger.finish(request_id, usage, status)
            if status != 'success':
                self.probe_path.write_text(json.dumps({'success': False, 'checkedAt': datetime.now(timezone.utc).isoformat(), 'status': status}), encoding='utf-8')

"""Persistent application budget, conservative CNY estimates, never a billing cap."""
import sqlite3
from pathlib import Path
from datetime import datetime, timezone
from ..errors import ServiceError

PRICE_SOURCE = 'https://api-docs.deepseek.com/zh-cn/quick_start/pricing/'
PRICE_VERIFIED = '2026-10-10'
INPUT_MISS = 2.0
INPUT_HIT = 0.04
OUTPUT = 8.0

class BudgetLedger:
    def __init__(self, path: Path, limit: float):
        path.parent.mkdir(parents=True, exist_ok=True)
        self.path, self.limit = path, limit
        with self.connect() as db:
            db.execute('CREATE TABLE IF NOT EXISTS calls (request_id TEXT PRIMARY KEY, created_at TEXT, status TEXT, reserved REAL, cost REAL, usage_json TEXT)')

    def connect(self):
        return sqlite3.connect(self.path, timeout=5)

    def summary(self) -> dict:
        with self.connect() as db:
            row = db.execute('SELECT count(*),coalesce(sum(coalesce(cost,reserved)),0) FROM calls').fetchone()
        return {'calls': row[0], 'estimatedUpperCostCny': round(row[1], 8), 'budgetCny': self.limit, 'priceVerifiedAt': PRICE_VERIFIED, 'priceSource': PRICE_SOURCE, 'estimateBasis': 'conservative peak tariff; unknown outcomes retain reservation; not provider billing cap'}

    def reserve(self, request_id: str, messages: list, max_output: int):
        import json
        # A byte-based upper estimate includes message formatting overhead.
        token_upper = len(json.dumps(messages, ensure_ascii=False).encode('utf-8')) + 256
        reserved = (token_upper * INPUT_MISS + max_output * OUTPUT) / 1_000_000
        with self.connect() as db:
            db.execute('BEGIN IMMEDIATE')
            total = db.execute('SELECT coalesce(sum(coalesce(cost,reserved)),0) FROM calls').fetchone()[0]
            if total + reserved > self.limit:
                raise ServiceError('TEST_BUDGET_EXCEEDED', '本阶段应用测试预算将超出3元，已暂停模型调用；需用户批准追加预算。', 429)
            db.execute('INSERT INTO calls VALUES (?,?,?,?,?,?)', (request_id, datetime.now(timezone.utc).isoformat(), 'reserved', reserved, None, None))

    def finish(self, request_id: str, usage: dict | None, status: str):
        import json
        cost = None
        safe_usage = None
        if isinstance(usage, dict) and usage:
            values = {k: usage[k] for k in ('prompt_tokens', 'completion_tokens', 'total_tokens', 'prompt_cache_hit_tokens', 'prompt_cache_miss_tokens') if isinstance(usage.get(k), int) and usage[k] >= 0}
            if 'prompt_tokens' in values and 'completion_tokens' in values:
                hit = min(values.get('prompt_cache_hit_tokens', 0), values['prompt_tokens'])
                miss = values['prompt_tokens'] - hit
                cost = (hit * INPUT_HIT + miss * INPUT_MISS + values['completion_tokens'] * OUTPUT) / 1_000_000
                safe_usage = json.dumps(values)
        # Known rejected HTTP requests incurred no generated tokens; transport/timeout are unknown.
        if status in ('http_400', 'http_401', 'http_402', 'http_404', 'http_429'):
            cost = 0.0
        with self.connect() as db:
            db.execute('UPDATE calls SET status=?,cost=?,usage_json=? WHERE request_id=?', (status, cost, safe_usage, request_id))

    def records(self):
        import json
        with self.connect() as db:
            rows = db.execute('SELECT request_id,created_at,status,reserved,cost,usage_json FROM calls ORDER BY created_at').fetchall()
        return [dict(requestId=r[0],createdAt=r[1],status=r[2],reservedUpperCny=r[3],estimatedUpperCny=r[4],usage=json.loads(r[5]) if r[5] else None) for r in rows]

